5	interface FocusTarget {
6	  rowIndex: number;
7	  columnIndex: number;
8	}
9	
10	const KEY_DELTAS: Record<string, { rowDelta: number; columnDelta: number }> = {
11	  ArrowUp: { rowDelta: -1, columnDelta: 0 },
12	  ArrowDown: { rowDelta: 1, columnDelta: 0 },
13	  ArrowLeft: { rowDelta: 0, columnDelta: -1 },
14	  ArrowRight: { rowDelta: 0, columnDelta: 1 }
15	};
