17	@Component({
18	  selector: 'app-seat-map',
19	  imports: [],
20	  templateUrl: './seat-map.html',
21	  styleUrl: './seat-map.scss'
22	})
23	export class SeatMapGrid {
24	  readonly seatMap = input.required<SeatMap>();
25	
26	  private readonly root = viewChild.required<ElementRef<HTMLElement>>('root');
27	
28	  private readonly focusTarget = signal<FocusTarget | null>(null);
29	
30	  private readonly firstFreeTarget = computed<FocusTarget | null>(() => {
31	    const rows = this.seatMap().rows;
32	    for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
33	      const columnIndex = rows[rowIndex].cells.findIndex(cell => cell.status === 'free');
34	      if (columnIndex !== -1) {
35	        return { rowIndex, columnIndex };
36	      }
37	    }
38	    return null;
39	  });
40	
41	  readonly hasFreeSeats = computed(() => this.firstFreeTarget() !== null);
42	
43	  constructor() {
44	    effect(() => {
45	      const target = this.focusTarget();
46	      if (target === null) {
47	        return;
48	      }
49	      const selector = `[data-row-index="${target.rowIndex}"][data-column-index="${target.columnIndex}"]`;
50	      this.root().nativeElement.querySelector<HTMLButtonElement>(selector)?.focus();
51	    });
52	  }
53	
54	  isRovingTabTarget(rowIndex: number, columnIndex: number): boolean {
55	    const current = this.focusTarget() ?? this.firstFreeTarget();
56	    return current !== null && current.rowIndex === rowIndex && current.columnIndex === columnIndex;
57	  }
58	
59	  ariaLabel(rowLabel: string, cell: SeatMapCell): string {
60	    const statusText = cell.status === 'occupied' ? 'belegt' : 'frei';
61	    return `Reihe ${rowLabel}, Platz ${cell.columnNumber}, ${statusText}`;
62	  }
63	
64	  onFocus(rowIndex: number, columnIndex: number): void {
65	    this.focusTarget.set({ rowIndex, columnIndex });
66	  }
67	
68	  onKeydown(event: KeyboardEvent, rowIndex: number, columnIndex: number): void {
69	    const delta = KEY_DELTAS[event.key];
70	    if (!delta) {
71	      return;
72	    }
73	    event.preventDefault();
74	    const next = this.findNextFocusable(rowIndex, columnIndex, delta.rowDelta, delta.columnDelta);
75	    if (next) {
76	      this.focusTarget.set(next);
77	    }
78	  }
79	
80	  private findNextFocusable(rowIndex: number, columnIndex: number, rowDelta: number, columnDelta: number): FocusTarget | null {
81	    const rows = this.seatMap().rows;
82	    let r = rowIndex + rowDelta;
83	    let c = columnIndex + columnDelta;
84	    while (r >= 0 && r < rows.length && c >= 0 && c < rows[r].cells.length) {
85	      if (rows[r].cells[c].status === 'free') {
86	        return { rowIndex: r, columnIndex: c };
87	      }
88	      r += rowDelta;
89	      c += columnDelta;
90	    }
91	    return null;
92	  }
93	}
